import SwiftUI
import UIKit

/// Non-colour tokens. Colours are in Palette.swift, generated by scripts/tokens.py.
enum Theme {
    enum Paper {
        /// Near-opaque so text never sits on foil. Mirrored in scripts/tokens.py PAPER_ALPHA, which checks contrast.
        static func opacity(_ scheme: ColorScheme) -> Double { scheme == .dark ? 0.92 : 0.94 }
    }

    enum Blur {
        static let panel: CGFloat = 20
    }

    enum Noise {
        static let opacity = 0.035 // mirrored in scripts/tokens.py NOISE
        static let grain: CGFloat = 1
    }

    enum DotGrid {
        static let spacing: CGFloat = 16
        static let diameter: CGFloat = 1.5
        static let opacity = 0.18
        static let tilt = Angle.degrees(60)   // rotation3DEffect around x
        static let perspective: CGFloat = 0.6
        static let fade = (near: 1.0, far: 0.0) // opacity at the bottom edge and at the horizon
    }

    enum Motion {
        /// Viscous: slow start, long settle, no overshoot. Never a spring with bounce.
        static func viscous(_ duration: Double = Duration.medium) -> Animation {
            .timingCurve(0.5, 0, 0.1, 1, duration: duration)
        }

        enum Duration {
            static let fast = 0.2, medium = 0.45, slow = 0.8
            static let flowCover = 0.5, flowDrain = 0.6 // screen change, 1.1 s total
            static let reducedMotionFade = 0.15
        }
    }

    enum Radius {
        static let small: CGFloat = 8, medium: CGFloat = 14, large: CGFloat = 22, panel: CGFloat = 28
    }

    /// zIndex values, back to front.
    enum Layer {
        static let foil = 0.0, dotGrid = 1.0, paper = 2.0, content = 3.0, flow = 10.0
    }

    enum Quality: Int {
        case low, medium, high

        /// p95 frame time above this steps down one tier.
        static let budgetMs = 16.6

        var lower: Quality { Quality(rawValue: max(rawValue - 1, 0))! }
        var foilBands: Int { [1, 2, 3][rawValue] }
        var animatesFoil: Bool { self != .low }
        var usesNoise: Bool { self == .high }
    }
}

/// Playfair (v2), SIL OFL 1.1 (Resources/Fonts/OFL.txt). Axis ranges read from the fvar table with fontTools.
enum Typeface {
    static let postScriptName = "Playfair-5ptSemiExpandedLight" // default instance; every use sets all axes

    enum Axis {
        static let wght: ClosedRange<CGFloat> = 300...900
        static let wdth: ClosedRange<CGFloat> = 87.5...112.5
        static let opsz: ClosedRange<CGFloat> = 5...1200
    }
}

struct TypeStyle {
    let size: CGFloat
    let weight: CGFloat
    let width: CGFloat
    let textStyle: UIFont.TextStyle
    /// Only these may animate axes. Body text stays static while it is read.
    let kinetic: Bool

    static let display = TypeStyle(size: 44, weight: 500, width: 100, textStyle: .largeTitle, kinetic: true)
    static let title = TypeStyle(size: 28, weight: 500, width: 100, textStyle: .title1, kinetic: true)
    static let headline = TypeStyle(size: 20, weight: 600, width: 100, textStyle: .headline, kinetic: true)
    static let numeral = TypeStyle(size: 34, weight: 400, width: 95, textStyle: .title1, kinetic: true)
    static let body = TypeStyle(size: 17, weight: 400, width: 100, textStyle: .body, kinetic: false)
    static let label = TypeStyle(size: 13, weight: 600, width: 105, textStyle: .footnote, kinetic: true)
}

extension Font {
    /// Playfair at explicit axis values. opsz follows the rendered size, so stroke contrast suits the size.
    // shortcut: Dynamic Type is read when the font is built, so a view only picks up a size change when it re-renders; read \.dynamicTypeSize in screens that need live updates.
    static func toodle(_ style: TypeStyle, weight: CGFloat? = nil, width: CGFloat? = nil) -> Font {
        let size = UIFontMetrics(forTextStyle: style.textStyle).scaledValue(for: style.size)
        let axes: [Int: CGFloat] = [
            0x7767_6874: clamped(weight ?? style.weight, Typeface.Axis.wght), // 'wght'
            0x7764_7468: clamped(width ?? style.width, Typeface.Axis.wdth),   // 'wdth'
            0x6F70_737A: clamped(size, Typeface.Axis.opsz),                   // 'opsz'
        ]
        let descriptor = UIFontDescriptor(fontAttributes: [
            .name: Typeface.postScriptName,
            UIFontDescriptor.AttributeName(rawValue: kCTFontVariationAttribute as String): axes,
        ])
        return Font(UIFont(descriptor: descriptor, size: size) as CTFont)
    }
}

private func clamped(_ value: CGFloat, _ range: ClosedRange<CGFloat>) -> CGFloat {
    min(max(value, range.lowerBound), range.upperBound)
}
